#!/usr/bin/env bash
# Frozen Yule (Christmas) stage assets + music.
set -u
G=/google/bin/releases/gemini-agents-generate/generate
STYLE='32-bit era (mid-1990s console) 2D pixel art for a gothic horror side-scrolling action platformer. Crisp hard-edged pixel clusters, limited palette, flat shading with 2-3 tones per material, no anti-aliasing blur, no painterly or photoreal rendering. Strict side view, orthographic. No text, no labels, no watermark, no signature, no frame borders.'
KEY='The background must be one flat solid pure bright green (#00FF00) with no gradient, no ground shadows, and nothing touching the image edges. Nothing green anywhere on the subjects: use dark blue-black for any foliage.'
gen() {
  local name="$1"; shift
  if [ -s "/tmp/gen_${name}.png" ]; then echo "= ${name} exists"; return; fi
  for attempt in 1 2 3; do
    "$G" -prod -timeout=180s -output="/tmp/gen_${name}.png" image -model=gempix-2-flash-lite-png "$STYLE $*" 2>&1 | grep -E "Successfully|rror|denied|capacity" | tail -1
    [ -s "/tmp/gen_${name}.png" ] && break
    sleep 15
  done
}
gen snowfloor "Palette: pale blue-white snow, ice blue, frozen dark umber earth, deep indigo shadows, grey stones. SIDE-VIEW TERRAIN CROSS-SECTION STRIP of snow-covered ground on a winter night, horizontally seamless (the left edge continues the right edge). The top 25 percent of the image is flat solid pure bright green (#00FF00) with nothing in it. At exactly 25 percent from the top is a perfectly horizontal surface of thick pale blue-white snow with a few icicles and small snow drifts poking slightly up into the green; below the surface, a band of packed snow and ice over frozen dark umber earth with embedded grey stones and dead roots, darker toward the bottom. No objects above the surface except the small drifts, no text."
gen winter "Palette: near-black indigo pine silhouettes, pale blue-white snow, warm amber and red window and lantern lights, deep indigo shadows. MID-DISTANCE PARALLAX BACKGROUND LAYER of a snowbound village on a winter night: a continuous row of dark indigo snow-laden pine trees, a small stone chapel with a pointed steeple and glowing amber windows, a few crooked cottages with snowy roofs and lit windows, lanterns on posts and two tall decorated fir trees strung with tiny red and amber lights; snow drifts and a solid pale snow ground fill across the bottom 12 percent so the bottom edge is completely filled. The layer must be horizontally seamless (the left edge continues the right edge), and the composition must fit within the middle horizontal band of the image (the top 20 percent and bottom 5 percent may be empty). Everything above the trees and roofs must be one flat solid pure bright green (#00FF00) with no gradient, no stars, no moon, no falling snow. Nothing green anywhere: the pines are dark indigo-black."
gen icecreatures "Palette: translucent ice blue and white, deep indigo cores, pale blue-white snow, coal black, carrot orange. SPRITE SHEET of winter enemies facing RIGHT, a 2 by 2 grid of cells with wide even green gaps, all at the same scale with feet on a shared baseline per row: top-left a hulking ice golem of jagged translucent ice blocks standing with arms hanging (walk frame 1), top-right the same ice golem mid-stride with one arm swung forward (walk frame 2), bottom-left a sinister living snowman with a crooked coal grin, twig arms and a black top hat standing idle, bottom-right the same snowman winding up to throw a snowball with one twig arm raised high. $KEY"
gen wisp "Palette: pale ice blue, white, deep indigo, faint violet. SPRITE SHEET of ONE frost wisp enemy facing RIGHT, a 2 by 2 grid of cells with wide even green gaps, all at the same scale: a floating skull-faced spirit of swirling ice crystals and snowflakes with two glowing pale-blue eyes and a trailing frosty tail, shown in four frames of its swirling animation (crystals rotating a quarter turn each frame). $KEY"
gen santa "Palette: deep crimson and black fur-trimmed coat, pale white fur, ashen grey skin, black horns, glowing yellow eyes, gold buckle, dark sack. SPRITE SHEET of ONE demonic Devil Santa boss facing RIGHT, a 2 by 2 grid of cells with wide even green gaps, all at the same scale with boots on a shared baseline: top-left standing menacingly with a huge dark sack over one shoulder and a cruel grin, top-right hurling a wrapped black-and-crimson gift box with one clawed hand, bottom-left lunging forward swinging a chain of iron bells, bottom-right staggering back in pain with his hat flying. Tall and broad, black curling horns through a crimson fur-trimmed hat, long white beard, clawed hands, heavy black boots. $KEY"
gen xmasprops "Palette: dark indigo-black fir needles (not green), warm amber, red and gold ornaments, pale snow, dark oak, candy-cane red and white. A ROW of 5 separate props for a haunted winter village platformer, in one horizontal row with wide even green gaps, strict side view, same scale, all standing on the same invisible baseline: (1) a tall decorated fir tree with dark indigo-black needles, snow on its boughs, red and gold baubles and tiny amber lights, (2) a wreath of dark indigo-black boughs with a red bow, (3) a candy-cane striped lamppost with a glowing amber lantern, (4) a pile of three wrapped gift boxes in crimson, black and gold, (5) a snow-covered dead stump with an icicle. $KEY"
ls -la /tmp/gen_snowfloor.png /tmp/gen_winter.png /tmp/gen_icecreatures.png /tmp/gen_wisp.png /tmp/gen_santa.png /tmp/gen_xmasprops.png
if [ ! -s /tmp/song_yule.mp3 ]; then
"$G" -timeout=600s -output="/tmp/song_yule.mp3" music -model=lyria-3-full-song-mp3 "Full-length instrumental video game stage theme (about two and a half minutes, with an intro, main theme, a contrasting bridge and a return to the main theme that can loop) for a gothic horror side-scrolling action platformer level set in a snowbound haunted village on Christmas night, 32-bit console era style. A sinister twisted Christmas theme in E minor at 150 BPM: driving sleigh bells and tubular bells, music-box and celesta melodies turned menacing, pipe organ, pizzicato strings, crunchy synth bass, crisp drums, choir swells, hints of a carol-like melody warped into a minor key. No vocals, no lyrics, instrumental only." 2>&1 | grep -E "Successfully|rror" | tail -1
fi
ls -la /tmp/song_yule.mp3
